'use strict';
(()=>{
const nav=[...document.querySelectorAll('aside nav button')].find(b=>b.textContent.trim()==='Рассылки');
const page=document.createElement('main');page.id='campaign-mail-check';page.hidden=true;
page.innerHTML=`<div class="breadcrumb">Коммуникации / Рассылки / Проверка письма</div>
<div class="heading"><div><h1 id="cmc-title">Проверка письма</h1><p id="cmc-source"></p></div><button class="outline" id="cmc-back">К рассылкам</button></div>
<div class="demo"><b>Без отправки писем</b><span>Проверка использует сохранённую копию рассылки. Тестовые события и отписки не меняют реальную клиентскую базу.</span></div>
<p id="cmc-status" role="status"></p><div class="actions cmc-tabs"><button class="outline" id="cmc-preview-tab">Проверка письма</button><button class="outline" id="cmc-stats-tab">Собственная статистика</button></div>
<section class="panel" id="cmc-preview-panel"><div class="section-title"><h2>Сохранённое письмо и отправитель</h2><button class="outline" id="cmc-reload">Обновить копию</button></div><dl id="cmc-meta"></dl>
<p>Изменения библиотеки шаблонов и списка отправителей не подменяют сохранённые данные рассылки. После создания очереди используется её копия.</p>
<h3>Данные для персонализации</h3><form id="cmc-search-form" class="cmc-grid"><label>Поиск клиента в получателях<input id="cmc-search" maxlength="160" placeholder="Название или email"></label><button class="outline">Найти</button></form>
<label>Клиент<select id="cmc-contact"><option value="">Ввести проверочные данные вручную</option></select></label><p id="cmc-client-note"></p>
<form id="cmc-form"><div class="cmc-grid"><label>Email для проверки<input id="cmc-recipient" type="email" value="preview@example.invalid" maxlength="254" required></label><label>Имя<input id="cmc-name" maxlength="250" value="Тестовый клиент"></label><label>Компания<input id="cmc-company" maxlength="250" value="OVER"></label><label>Город<input id="cmc-city" maxlength="250" value="Алматы"></label></div>
<p>Выбранные данные можно изменить только в этой проверке. Карточка клиента не меняется. Согласие на рассылку и доставка не подтверждаются.</p>
<div class="actions"><button class="outline" type="submit" id="cmc-diagnose">Проверить подстановку и ссылки</button><button class="outline" type="button" id="cmc-prepare">Подготовить проверочное письмо</button></div></form>
<div id="cmc-diagnosis" class="table-scroll"></div><p id="cmc-missing"></p>
<div id="cmc-result" hidden><h3 id="cmc-subject"></h3><div id="cmc-actions" class="actions"></div><p id="cmc-result-note" role="status"></p>
<iframe id="cmc-frame" title="Проверочное письмо рассылки" sandbox="" referrerpolicy="no-referrer"></iframe>
<details><summary>Подготовленный HTML и заголовки</summary><textarea id="cmc-html" readonly aria-label="HTML проверочного письма рассылки"></textarea><pre id="cmc-headers"></pre></details></div></section>
<section class="panel" id="cmc-stats-panel" hidden><div class="section-title"><h2>События этой рассылки</h2><button class="outline" id="cmc-refresh-stats">Обновить события</button></div>
<form id="cmc-filters" class="cmc-grid"><label>Источник<select id="cmc-mode"><option value="test">Проверочные письма</option><option value="real">Рабочие письма</option></select></label><label>Письмо<select id="cmc-message"><option value="">Все письма этой рассылки</option></select></label>
<label>Email<input id="cmc-query" maxlength="254" placeholder="Поиск получателя"></label><label>Событие<select id="cmc-kind"><option value="">Все события</option><option value="open">Открытие</option><option value="click">Переход</option><option value="unsubscribe">Отписка</option></select></label>
<label>С даты<input id="cmc-from" type="date"></label><label>По дату включительно<input id="cmc-to" type="date"></label>
<label>Сортировка<select id="cmc-direction"><option value="desc">Сначала новые</option><option value="asc">Сначала старые</option></select></label><button class="outline">Применить</button></form>
<p id="cmc-stats-status" role="status"></p><div class="stats" id="cmc-cards"></div><div id="cmc-history" class="table-scroll"></div><div class="actions"><button class="outline" id="cmc-prev">Назад</button><span id="cmc-pagination"></span><button class="outline" id="cmc-next">Далее</button></div>
<p>Карточки — уникальные email и число первых событий за выбранный период. Журнал — по выбранному типу события. Открытие означает загрузку пикселя, переход может выполнить почтовая проверка. Доставка и прочтение этим не доказываются. Синтетические события прежней демо-статистики сюда не попадают.</p></section>`;
document.body.append(page);
const $=key=>document.getElementById('cmc-'+key),store='campaign-mail-check-open',labels={open:'Открытие',click:'Переход',unsubscribe:'Отписка'};
let campaignId=null,context=null,clients=[],tab='preview',generation=0,statsGeneration=0,searchGeneration=0,currentPage=1,busy=false,preparedPreview=null;
function text(tag,value){const el=document.createElement(tag);el.textContent=value??'';return el;}
function table(host,head,rows){const table=document.createElement('table'),thead=document.createElement('thead'),tr=document.createElement('tr');table.setAttribute('role','table');table.setAttribute('aria-label',host.id==='cmc-history'?'Журнал событий рассылки':'Результаты проверки письма');for(const value of head){const th=text('th',value);th.scope='col';tr.append(th);}thead.append(tr);table.append(thead);const tbody=document.createElement('tbody');for(const row of rows){const tr=document.createElement('tr');row.forEach((value,index)=>{const td=text('td',value);td.dataset.label=head[index];tr.append(td);});tbody.append(tr);}if(!rows.length){const tr=document.createElement('tr'),td=text('td','Пока нет событий');td.colSpan=head.length;tr.className='cmc-empty';tr.append(td);tbody.append(tr);}table.append(tbody);host.replaceChildren(table);}
function remember(){try{sessionStorage.setItem(store,JSON.stringify({id:campaignId,tab}));}catch{}}
function invalidate(){generation++;preparedPreview=null;$('result').hidden=true;$('frame').srcdoc='';$('html').value='';$('headers').textContent='';$('actions').replaceChildren();$('diagnosis').replaceChildren();$('missing').textContent='';}
function switchTab(value){tab=value;$('preview-panel').hidden=tab!=='preview';$('stats-panel').hidden=tab!=='stats';$('preview-tab').setAttribute('aria-pressed',String(tab==='preview'));$('stats-tab').setAttribute('aria-pressed',String(tab==='stats'));remember();if(tab==='stats')report();else renderPreparedPreview();}
function showContext(r){context=r;$('title').textContent=r.campaign_name;$('source').textContent=r.note;const meta=$('meta');meta.replaceChildren();for(const [key,value]of [['Версия рассылки',r.version.campaign_revision],['Шаблон',`${r.template.name||'Без названия'} · версия ${r.template.revision||'—'}`],['Тема',r.template.subject],['Отправитель',`${r.sender.name||''} <${r.sender.email||''}>`],['Ответы',r.sender.reply_to||r.sender.email||'Не задано']])meta.append(text('dt',key),text('dd',value));}
function fillClients(r){clients=r.clients;$('contact').replaceChildren(new Option('Ввести проверочные данные вручную',''));for(const c of clients)$('contact').add(new Option(`${c.label} · ${c.email||'без email'}`,String(c.id)));$('client-note').textContent=r.clients_more?'Показаны первые 20 контактов. Уточните поиск, чтобы найти нужного клиента.':'Клиенты из получателей этой рассылки. Выбор без email потребует указать проверочный адрес.';}
async function reload(){const id=campaignId;const seq=++searchGeneration;const r=await api(`/api/campaigns/${id}/mail-check?`+new URLSearchParams({query:$('search').value}));if(id!==campaignId||seq!==searchGeneration)return;invalidate();showContext(r);fillClients(r);$('status').textContent='Сохранённые данные загружены. Письма не отправляются.';}
function input(){return {version:context?.version,recipient:$('recipient').value,values:{name:$('name').value,company:$('company').value,city:$('city').value},contact_id:$('contact').value?Number($('contact').value):null,is_test:true,send:false};}
function diagnosis(r){table($('diagnosis'),['Проверка','Состояние','Описание'],r.checks.map(c=>[c.title,{pass:'Готово',fail:'Ошибка',warning:'Замечание',pending:'Не проверено'}[c.status],c.detail]));$('missing').textContent=r.missing.length?'Не хватает данных: '+r.missing.map(k=>'{{'+k+'}}').join(', '):'Недостающих значений для использованных переменных нет.';for(const f of r.findings){$('diagnosis').append(text('p',f.message));}}
function safePreview(html){const d=new DOMParser().parseFromString(html,'text/html');for(const t of d.querySelectorAll('script,iframe,form,object,embed,meta,link,base'))t.remove();for(const a of d.querySelectorAll('a,area')){a.removeAttribute('href');a.removeAttribute('target');}return `<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; form-action 'none'; base-uri 'none'">`+d.documentElement.outerHTML;}
function renderPreparedPreview(){
if(!preparedPreview||tab!=='preview'||$('result').hidden)return;
const prepared=preparedPreview,frame=$('frame').cloneNode(false);
$('frame').replaceWith(frame);
// Mount in the visible panel before navigating srcdoc; hidden iframe reloads can stay blank.
requestAnimationFrame(()=>{if(frame.isConnected&&prepared===preparedPreview&&tab==='preview'&&!$('result').hidden)frame.srcdoc=prepared.html;});
}
function showPrepared(r){$('result').hidden=false;$('subject').textContent=r.subject;preparedPreview={html:safePreview(r.html)};renderPreparedPreview();$('html').value=r.html;$('headers').textContent=JSON.stringify(r.headers,null,2);$('actions').replaceChildren();const id=campaignId;
function action(label,url,click){const b=text('button',label);b.className='outline';b.type='button';b.onclick=async()=>{b.disabled=true;try{const response=await fetch(url,{redirect:click?'manual':'follow',cache:'no-store',referrerPolicy:'no-referrer'});if(response.type!=='opaqueredirect'&&!response.ok)throw Error('Ссылка недоступна.');if(id!==campaignId)return;$('result-note').textContent='Проверочное событие записано для этой рассылки. Повторы одной ссылки не увеличивают счётчик.';if(tab==='stats')await report();}catch(e){if(id===campaignId)$('result-note').textContent=e.message;}finally{b.disabled=false;}};$('actions').append(b);}
action('Проверить открытие',r.pixel_url,false);r.clicks.forEach((c,i)=>action('Проверить переход '+(i+1),c.url,true));const link=text('a','Открыть проверочную отписку');link.href=r.unsubscribe_url;link.target='_blank';link.rel='noopener noreferrer';link.className='outline';$('actions').append(link);const stats=text('button','Статистика этого письма');stats.type='button';stats.className='outline';stats.onclick=()=>{$('mode').value='test';$('query').value='';$('kind').value='';$('from').value='';$('to').value='';$('message').replaceChildren(new Option('Все письма этой рассылки',''),new Option(r.subject,r.id));$('message').value=r.id;currentPage=1;switchTab('stats');};$('actions').append(stats);$('result-note').textContent=r.note;}
async function check(action){if(busy||!context)return;const seq=++generation,id=campaignId;const payload={...input(),action};busy=true;$('prepare').disabled=true;$('diagnose').disabled=true;try{const response=await fetch(`/api/campaigns/${id}/mail-check`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRFToken':document.cookie.split('; ').find(c=>c.startsWith('sales_csrftoken='))?.split('=')[1]||''},body:JSON.stringify(payload)});const r=await response.json();if(seq!==generation||id!==campaignId)return;if(r.diagnosis)diagnosis(r.diagnosis);if(!response.ok){if(response.status===409){invalidate();context=null;}throw Error(r.error||'Не удалось проверить письмо.');}diagnosis(r.diagnosis||r);if(action==='prepare')showPrepared(r);$('status').textContent=action==='prepare'?'Проверочное письмо подготовлено. Отправка не выполнялась.':r.can_prepare?'Проверка пройдена. Можно подготовить письмо без отправки.':'Проверка выявила ошибки. Исправьте данные перед подготовкой.';}catch(e){if(id===campaignId&&seq===generation||id===campaignId&&!context)$('status').textContent=e.message;}finally{busy=false;$('prepare').disabled=!context;$('diagnose').disabled=!context;}}
async function report(){const seq=++statsGeneration,id=campaignId;try{const params=new URLSearchParams({campaign_id:String(id),mode:$('mode').value,kind:$('kind').value,query:$('query').value,direction:$('direction').value,from:$('from').value,to:$('to').value,page:String(currentPage)});if($('message').value)params.set('message_id',$('message').value);const r=await api('/api/mail-tracking?'+params);if(seq!==statsGeneration||id!==campaignId)return;
$('cards').replaceChildren();for(const [kind,title]of Object.entries({open:'Открытия',click:'Переходы',unsubscribe:'Отписки'})){const card=document.createElement('article');card.append(text('span',title),text('strong',r.unique[kind]),text('small',`Уникальных email · первых событий: ${r.totals[kind]}`));$('cards').append(card);}
table($('history'),['Время','Получатель','Тема','Версия рассылки','Событие','Ссылка'],r.history.map(e=>[new Date(e.occurred_at).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'}),e.recipient,e.subject,e.preparation_snapshot?.version?.campaign_revision||'—',labels[e.kind],e.target]));$('stats-status').textContent=`${r.campaign_name} · ${r.mode==='test'?'проверочные':'рабочие'} письма: ${r.messages_count}. Отправка отключена.`;
$('pagination').textContent=`${r.pagination.page} / ${r.pagination.pages} · событий: ${r.pagination.total}`;$('prev').disabled=!r.pagination.has_previous;$('next').disabled=!r.pagination.has_next;
if(!$('message').value){$('message').replaceChildren(new Option('Все письма этой рассылки',''));for(const m of r.messages)$('message').add(new Option(`${m.recipient} · ${m.subject}`,m.id));}
}catch(e){if(seq===statsGeneration&&id===campaignId)$('stats-status').textContent=e.message;}}
$('back').onclick=()=>{try{sessionStorage.removeItem(store);}catch{}nav.click();};$('reload').onclick=()=>reload().catch(e=>$('status').textContent=e.message);$('preview-tab').onclick=()=>switchTab('preview');$('stats-tab').onclick=()=>switchTab('stats');
$('search-form').onsubmit=async e=>{e.preventDefault();try{const id=campaignId,seq=++searchGeneration;const r=await api(`/api/campaigns/${id}/mail-check?`+new URLSearchParams({query:$('search').value}));if(seq!==searchGeneration||id!==campaignId)return;invalidate();showContext(r);fillClients(r);}catch(error){$('status').textContent=error.message;}};
$('contact').onchange=()=>{invalidate();const c=clients.find(c=>c.id===Number($('contact').value));if(!c)return;$('recipient').value=c.email||'preview@example.invalid';for(const key of ['name','company','city'])$(key).value=c.values[key]||'';};$('form').oninput=invalidate;$('form').onsubmit=e=>{e.preventDefault();check('diagnose');};$('prepare').onclick=()=>{if($('form').reportValidity())check('prepare');};
$('filters').onsubmit=e=>{e.preventDefault();currentPage=1;report();};$('mode').onchange=()=>{$('message').replaceChildren(new Option('Все письма этой рассылки',''));currentPage=1;report();};$('refresh-stats').onclick=report;$('prev').onclick=()=>{currentPage=Math.max(1,currentPage-1);report();};$('next').onclick=()=>{currentPage++;report();};
document.querySelector('aside nav').addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;page.hidden=true;generation++;statsGeneration++;searchGeneration++;try{sessionStorage.removeItem(store);}catch{}});
window.CampaignMailCheck={async open(id,initialTab='preview'){nav.click();generation++;statsGeneration++;searchGeneration++;campaignId=Number(id);context=null;clients=[];invalidate();$('status').textContent='Загрузка сохранённой рассылки…';$('prepare').disabled=true;$('diagnose').disabled=true;$('search').value='';$('recipient').value='preview@example.invalid';$('name').value='Тестовый клиент';$('company').value='OVER';$('city').value='Алматы';$('contact').replaceChildren(new Option('Ввести проверочные данные вручную',''));$('mode').value='test';for(const key of ['query','kind','from','to'])$(key).value='';$('message').replaceChildren(new Option('Все письма этой рассылки',''));currentPage=1;document.querySelectorAll('body>main').forEach(p=>p.hidden=true);page.hidden=false;document.title='Проверка письма рассылки';switchTab(initialTab);try{await reload();$('prepare').disabled=false;$('diagnose').disabled=false;}catch(e){$('status').textContent=e.message;}}};
try{const saved=JSON.parse(sessionStorage.getItem(store)||'null');if(saved?.id)window.CampaignMailCheck.open(saved.id,saved.tab);}catch{}
})();
